from typing import Iterable, Optional, Dict
from searcharray.postings import SearchArray, ws_tokenizer

class SearchArray:
    def index(cls, array: Iterable, tokenizer=ws_tokenizer,
              truncate=False, batch_size=100000, avoid_copies=True) -> 'SearchArray':

        # Initialize the SearchArray instance
        indexed_array = cls()

        # Initialize the term dictionary and postings
        indexed_array.term_dict = {}
        indexed_array.postings = {}

        # Initialize the document lengths and positions
        indexed_array.doc_lens = []
        indexed_array.posns = {}

        # Initialize the average document length
        indexed_array.avg_doc_len = 0

        # Process the array in batches if necessary
        for i in range(0, len(array), batch_size):
            batch = array[i:i+batch_size]

            # Tokenize the strings in the batch using the specified tokenizer
            tokens = [tokenizer(string) for string in batch]

            # Update the term dictionary
            for token in tokens:
                if token not in indexed_array.term_dict:
                    indexed_array.term_dict[token] = len(indexed_array.term_dict)

            # Update the postings for each token in the batch
            for j, token in enumerate(tokens):
                if token not in indexed_array.postings:
                    indexed_array.postings[token] = []
                indexed_array.postings[token].append((j, len(batch)))

            # Update the document lengths
            indexed_array.doc_lens.extend([len(batch)] * batch_size)

        # Update the average document length
        indexed_array.avg_doc_len = sum(indexed_array.doc_lens) / len(indexed_array.doc_lens)

        # Update the positions
        for token in indexed_array.postings:
            indexed_array.posns[token] = {}
            for i, (pos, doc_len) in enumerate(indexed_array.postings[token]):
                if pos not in indexed_array.posns[token]:
                    indexed_array.posns[token][pos] = []
                indexed_array.posns[token][pos].append(doc_len)

        # Return the indexed SearchArray instance
        return indexed_array
```

