def bit_count64(arr):
    """
    Counts the number of bits set to 1 (also known as the Hamming weight or the population count) in each element of a 64-bit integer array using bitwise operations.

    This is a step in the process of efficiently calculating the bit count for each element in the array.

    Input-Output Arguments
    :param arr: Array of 64-bit integers. The array whose elements' bit counts are to be calculated. It is modified in-place to contain the bit counts as its elements.
    :return: Array of integers. The same array passed as input, but now each element has been replaced with its corresponding bit count.
    """

    # Function to count the number of bits set to 1 in a 64-bit integer
    def bitcount(n):
        count = 0
        while n:
            count += n & 1
            n >>= 1
        return count

    # Function to count the number of bits set to 1 in the least significant 32 bits of a 64-bit integer
    def s0F(n):
        return bitcount(n & 0xFFFFFFFF)

    # Function to count the number of bits set to 1 in the most significant 32 bits of a 64-bit integer
    def s01(n):
        return bitcount((n >> 32) & 0xFFFFFFFF)

    # Function to count the number of bits set to 1 in all but one bit of a 64-bit integer
    def all_but_one_bit(n):
        return s0F(n) + s01(n)

    # Function to count the number of bits set to 1 in a 64-bit integer
    def _4(n):
        return all_but_one_bit(n)

    # Iterate over each element in the array and calculate its bit count
    for i in range(len(arr)):
        arr[i] = _4(arr[i])

    return arr
