def parse_min_should_match(num_clauses: int, spec: str) -> int:
    """
    This function parses the "min should match" specification (commonly referred to as 'mm' spec) from Solr's search engine configuration and calculates the minimum number of clauses that must match based on the given specification and the total number of clauses. It supports both absolute and percentage-based specifications, as well as conditional specifications using '<'.

    Input-Output Arguments
    :param num_clauses: int, the total number of clauses in the query.
    :param spec: str, the 'min should match' specification as a string, which can include absolute numbers, percentages, and conditional expressions.
    :return: int, the calculated minimum number of clauses that must match according to the 'mm' spec.
    """

    # Check if the specification is a conditional expression
    if '<' in spec:
        # Split the specification into two parts at the '<' character
        parts = spec.split('<')

        # Calculate the minimum number of clauses based on the conditional expression
        if len(parts) == 2:
            try:
                min_clauses = int(parts[0])
                max_clauses = int(parts[1])
                return max(min_clauses, num_clauses * min(max_clauses / 100, 1))
            except ValueError:
                raise ValueError("Invalid conditional specification")
        else:
            raise ValueError("Invalid conditional specification")

    # Check if the specification contains a percentage sign
    elif '%' in spec:
        # Calculate the minimum number of clauses based on the percentage
        try:
            percentage = float(spec.replace('%', '')) / 100
            return int(num_clauses * percentage)
        except ValueError:
            raise ValueError("Invalid percentage specification")

    # If the specification does not contain a percentage sign, it is assumed to be an absolute number
    else:
        # Check if the absolute number is valid
        try:
            return int(spec)
        except ValueError:
            raise ValueError("Invalid absolute specification")
